/**
 * Component: 3D product Card
 * Author: @nicole-shalom (https://tailwindflex.com/@nicole-shalom)
 * Source: https://tailwindflex.com/@nicole-shalom/3d-product-card
 * Attribution: Créé par @nicole-shalom sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function Comp3dProductCard() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>3D Product Card (Light)</title>

  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600&display=swap');
    * {
      font-family: 'Inter', sans-serif;
    }

    .card-3d {
      perspective: 1000px;
    }

    .card-inner {
      transition: transform 0.8s ease;
      transform-style: preserve-3d;
    }

    .card-3d:hover .card-inner {
      transform: rotateY(-10deg) rotateX(5deg) scale(1.02);
    }

    .product-image {
      transition: transform 0.5s ease;
    }

    .card-3d:hover .product-image {
      transform: scale(1.05) rotateY(5deg);
    }

    .btn-3d {
      transition: all 0.3s ease;
    }

    .btn-3d:hover {
      transform: scale(1.05);
    }
  </style>
</head>
<body class="min-h-screen bg-white text-black flex items-center justify-center p-4">

  <div class="card-3d">
    <div class="card-inner w-96 h-[520px] bg-gray-50 border border-gray-200 rounded-2xl shadow-xl overflow-hidden p-6 flex flex-col justify-between">

      <!-- Header -->
      <div class="flex justify-between items-start">
        <span class="text-xs font-semibold bg-black text-white px-3 py-1 rounded-full">PREMIUM</span>
        <button class="text-gray-500 hover:text-black transition">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
              d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
          </svg>
        </button>
      </div>

      <!-- Product Image -->
      <div class="flex justify-center my-4">
        <img src="https://images.unsplash.com/photo-1572635196237-14b3f281503f?w=300&h=300&fit=crop&auto=format" 
             alt="Headphones" class="product-image w-48 h-48 object-contain" />
      </div>

      <!-- Product Info -->
      <div>
        <h3 class="text-xl font-bold mb-1">Wireless Headphones</h3>
        <p class="text-gray-600 text-sm mb-2">Crisp audio and noise cancellation.</p>

        <!-- Ratings -->
        <div class="flex items-center space-x-2 mb-3">
          <div class="flex text-yellow-400">
            <svg class="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M10 15l-5.878 3.09L5.64 12.18.762 7.91l6.093-.885L10 1l3.145 6.025 6.093.885-4.878 4.27 1.518 5.91z"/></svg>
            <svg class="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M10 15l-5.878 3.09L5.64 12.18.762 7.91l6.093-.885L10 1l3.145 6.025 6.093.885-4.878 4.27 1.518 5.91z"/></svg>
            <svg class="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M10 15l-5.878 3.09L5.64 12.18.762 7.91l6.093-.885L10 1l3.145 6.025 6.093.885-4.878 4.27 1.518 5.91z"/></svg>
            <svg class="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M10 15l-5.878 3.09L5.64 12.18.762 7.91l6.093-.885L10 1l3.145 6.025 6.093.885-4.878 4.27 1.518 5.91z"/></svg>
            <svg class="w-4 h-4 text-gray-300 fill-current" viewBox="0 0 20 20"><path d="M10 15l-5.878 3.09L5.64 12.18.762 7.91l6.093-.885L10 1l3.145 6.025 6.093.885-4.878 4.27 1.518 5.91z"/></svg>
          </div>
          <span class="text-gray-500 text-sm">4.8 (2.1k reviews)</span>
        </div>

        <!-- Price -->
        <div class="flex justify-between items-center mb-4">
          <div class="text-lg font-semibold text-black">
            $299 <span class="line-through text-gray-400 text-sm">$399</span>
          </div>
          <span class="bg-black text-white text-xs px-2 py-1 rounded-full">25% OFF</span>
        </div>

        <!-- Buttons -->
        <div class="flex space-x-3">
          <button class="btn-3d flex-1 bg-black text-white py-2 rounded-xl font-semibold">Add to Cart</button>
          <button class="btn-3d px-4 py-2 border border-black rounded-xl">
            <svg class="w-5 h-5 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S3.732 16.057 2.458 12z" />
            </svg>
          </button>
        </div>
      </div>

    </div>
  </div>

</body>
</html>" }} />
  );
}
